--
-- Estructura para la vista `ps_productos`
--
DROP TABLE IF EXISTS `ps_productos`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `ps_productos`  AS SELECT `p`.`ID` AS `id_product`, NULL AS `id_product_attribute`, trim(`sku_main`.`meta_value`) AS `refprod`, NULL AS `refatrib`, `p`.`post_title` AS `name`, `p`.`post_type` AS `post_type`, concat('https://www.fervicom.com/producto/',`p`.`post_name`) AS `plink`, `img_url`.`guid` AS `id_image` FROM (((`fervicom_wordpress`.`wp_posts` `p` left join `fervicom_wordpress`.`wp_postmeta` `sku_main` on(`sku_main`.`post_id` = `p`.`ID` and `sku_main`.`meta_key` = '_sku')) left join `fervicom_wordpress`.`wp_postmeta` `thumb` on(`thumb`.`post_id` = `p`.`ID` and `thumb`.`meta_key` = '_thumbnail_id')) left join `fervicom_wordpress`.`wp_posts` `img_url` on(`img_url`.`ID` = `thumb`.`meta_value`)) WHERE `p`.`post_type` = 'product' AND `p`.`post_status` = 'publish'union all select `v`.`post_parent` AS `id_product`,`v`.`ID` AS `id_product_attribute`,trim(`parent_sku`.`meta_value`) AS `refprod`,trim(`sku_var`.`meta_value`) AS `refatrib`,`parent`.`post_title` AS `name`,`v`.`post_type` AS `post_type`,concat('https://www.fervicom.com/producto/',`parent`.`post_name`) AS `plink`,`img_url`.`guid` AS `id_image` from (((((`fervicom_wordpress`.`wp_posts` `v` join `fervicom_wordpress`.`wp_posts` `parent` on(`parent`.`ID` = `v`.`post_parent` and `parent`.`post_type` = 'product' and `parent`.`post_status` = 'publish')) left join `fervicom_wordpress`.`wp_postmeta` `parent_sku` on(`parent_sku`.`post_id` = `parent`.`ID` and `parent_sku`.`meta_key` = '_sku')) left join `fervicom_wordpress`.`wp_postmeta` `sku_var` on(`sku_var`.`post_id` = `v`.`ID` and `sku_var`.`meta_key` = '_sku')) left join `fervicom_wordpress`.`wp_postmeta` `thumb` on(`thumb`.`post_id` = `parent`.`ID` and `thumb`.`meta_key` = '_thumbnail_id')) left join `fervicom_wordpress`.`wp_posts` `img_url` on(`img_url`.`ID` = `thumb`.`meta_value`)) where `v`.`post_type` = 'product_variation' and `v`.`post_status` = 'publish'  ;

-- --------------------------------------------------------

--
-- Estructura para la vista `v_saldo_vitrina`
--
DROP TABLE IF EXISTS `v_saldo_vitrina`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_saldo_vitrina`  AS SELECT `p`.`id` AS `id`, `p`.`codigo` AS `codigo`, `p`.`descripcion` AS `descripcion`, coalesce((select sum(case when `mu`.`tipo_movimiento` = 'ENTRADA' then `mu`.`cantidad` when `mu`.`tipo_movimiento` = 'SALIDA' then -`mu`.`cantidad` else 0 end) from `movimiento_ubicacion` `mu` where `mu`.`id_producto` = `p`.`id` and `mu`.`ubicacion` = 'Vitrina'),0) AS `saldo_vitrina` FROM `c_productos` AS `p` WHERE `p`.`estado` = 1 ;

